INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(53811, 'Ezekiel 9:6', 'Ezekiel', 9, 6, 'زاړه، ځوانان، پېغلې، ښځې او ماشومان ووژنئ. خو د چا په تندي چې نښه لګېدلې وي هغه ته کوم زیان ونه رسوئ. دا کار زما له کوره پیل کړئ.» نو هغوی دا کار د هغو مشرانو څخه پیل کړ چې د څښتن د کور په مخکې ولاړ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel9_verse_6.mp3', '', 1761754199, 1761754199),
(53812, 'Ezekiel 9:7', 'Ezekiel', 9, 7, 'بیا څښتن هغو شپږو کسانو ته وویل: «زما کور داسې ناپاکه کړئ چې د عبادت وړ نه وي. حوېلۍ د وژل شویو خلکو څخه ډکه کړئ. نو لاړ شئ او دا کار وکړئ!» وروسته هغوی په ښار کې د خلکو په وژلو پیل وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel9_verse_7.mp3', '', 1761754199, 1761754199),
(53813, 'Ezekiel 9:8', 'Ezekiel', 9, 8, 'په داسې حال کې چې د خلکو وژنه روانه وه، نو زه په هغه ځای کې یوازې پاتې شوم. زه په ځمکه باندې پرېوتم او زاري مې وکړه: «ای څښتن تعالی، ایا ته په اورشلیم باندې دومره په قهر یې چې غواړې په اسراییلو کې هرڅوک چې ژوندی پاتې وي، هغه ووژنې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel9_verse_8.mp3', '', 1761754199, 1761754199),
(53814, 'Ezekiel 9:9', 'Ezekiel', 9, 9, 'څښتن په ځواب کې وویل: «د اسراییلو او یهودا د قوم ګناهونه بې‌حده ډېر دي. هېواد یې په وینو رنګ او ښار د بې‌انصافۍ نه ډک دی. خلک وایي: ‹څښتن مونږ نه ویني، ځکه چې هغه دا هېواد پریښی دی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel9_verse_9.mp3', '', 1761754199, 1761754199),
(53815, 'Ezekiel 9:10', 'Ezekiel', 9, 10, 'خو زه به هغوی ته د مینې په سترګه ونه ګورم او په هغوی باندې به هېڅ رحم ونه کړم. د هغوی د بدو کړنو له امله به هغوی ته سزا ورکړم.»‎', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel9_verse_10.mp3', '', 1761754199, 1761754199),
(53816, 'Ezekiel 9:11', 'Ezekiel', 9, 11, 'بیا هغه سړی چې د کتان کالي یې اغوستي وو او د لیکلو سامان یې په ملا پورې تړلی ؤ، بېرته راستون شو او څښتن ته یې دا خبر راوړ: «کوم حکم چې تا ماته کړی ؤ، هغه مې سرته ورساوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel9_verse_11.mp3', '', 1761754199, 1761754199),
(53817, 'Isaiah 13:1', 'Isaiah', 13, 1, 'دا هغه پیغام دی چې د بابل په اړه د خدای له خوا د آموص زوی اشعیا ته ورسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_1.mp3', '', 1761754199, 1761754199),
(53818, 'Isaiah 13:2', 'Isaiah', 13, 2, 'د وچې غونډۍ په سر د جګړې بیرغ ورپوئ! عسکرو ته چیغې ووهئ او خپل لاسونه ورته د اشارې په توګه پورته کړئ چې د ښار د شریفو خلکو په دروازو حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_2.mp3', '', 1761754199, 1761754199),
(53819, 'Isaiah 13:3', 'Isaiah', 13, 3, 'څښتن خپله خپلو تکړه او ډاډمنو جنګیالیو ته حکم کړی چې وجنګیږي او هغو خلکو ته چې هغه ورباندې په قهر دی، سزا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_3.mp3', '', 1761754199, 1761754199),
(53820, 'Isaiah 13:4', 'Isaiah', 13, 4, 'هغه شورماشور ته غوږ ونیسئ چې په غرونو راپورته شوی دی، د خلکو د لویې ګڼې ګوڼې اوازونو ته، د پاچاهیو او قومونو د خلکو د راغونډېدلو اوازونو ته غوږ ونیسئ. مطلق قادر څښتن خپلې لښکرې د جګړې دپاره تیاروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_4.mp3', '', 1761754199, 1761754199),
(53821, 'Isaiah 13:5', 'Isaiah', 13, 5, 'هغوی د لېرې لېرې وطنونو او د نړۍ د بل سر څخه راځي. دا د څښتن وسله ده چې خپل قهر څرګندوي او هغه به ټوله نړۍ ورانه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_5.mp3', '', 1761754199, 1761754199),
(53822, 'Isaiah 13:6', 'Isaiah', 13, 6, 'ژړا او انګولا کوئ! ځکه چې د څښتن ورځ رانژدې ده، هغه ورځ چې مطلق قادر خدای به ټول له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_6.mp3', '', 1761754199, 1761754199),
(53823, 'Isaiah 13:7', 'Isaiah', 13, 7, 'په دې خاطر د هر چا لاسونه به سست شي او د ټولو خلکو زړونه به اوبه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_7.mp3', '', 1761754199, 1761754199),
(53824, 'Isaiah 13:8', 'Isaiah', 13, 8, 'هغوی ټول به سخت ووېریږي او په دردونو به اخته شي، په داسې درد لکه څنګه چې یوې ښځې ته د لنګون په وخت کې پیدا کیږي. هغوی به یو بل ته وګوري او د بدل شویو څېرو په لیدلو سره به حیران او په وېره کې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_8.mp3', '', 1761754199, 1761754199),
(53825, 'Isaiah 13:9', 'Isaiah', 13, 9, 'ګورئ، د څښتن ورځ راروانه ده. هغه بې رحمه او د سختې غوسې او د غضب نه ډکه ورځ ده. ځمکه به ورانه او ټول ګناهکاران به له منځه لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_9.mp3', '', 1761754199, 1761754199),
(53826, 'Isaiah 13:10', 'Isaiah', 13, 10, 'په اسمان کې به ستوري رڼا نه ورکوي. کله چې لمر راوخېژي نو هغه به تیاره وي او سپوږمۍ به رڼا نه ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_10.mp3', '', 1761754199, 1761754199),
(53827, 'Isaiah 13:11', 'Isaiah', 13, 11, 'څښتن وایي: «زه به په نړۍ افت نازل کړم او ټولو بدعمله خلکو ته به د هغوی د ګناهونو په خاطر سزا ورکړم. زه به د خلکو غرور او کبر پای ته ورسوم او هر مغرور او ظالم به ذلیل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_11.mp3', '', 1761754199, 1761754199),
(53828, 'Isaiah 13:12', 'Isaiah', 13, 12, 'ژوندي پاتې شوي خلک به د سوچه سرو زرو او انسانان به د اوفیر د سرو زرو نه لږ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_12.mp3', '', 1761754199, 1761754199),
(53829, 'Isaiah 13:13', 'Isaiah', 13, 13, 'په هغه ورځ چې زه مطلق قادر څښتن خپل سخت قهر څرګنده کړم نو اسمانونه به ولړزوم او ځمکه به له خپله ځایه وخوځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_13.mp3', '', 1761754199, 1761754199),
(53830, 'Isaiah 13:14', 'Isaiah', 13, 14, 'کوم پردي خلک چې په بابل کې اوسیږي هغوی به په تېښته خپلو قومونو او وطنونو ته داسې راستانه شي لکه هوسۍ چې له ښکاریانو تښتي یا لکه پسونه چې پرته د شپون نه هرې خواته خواره واره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_14.mp3', '', 1761754199, 1761754199),
(53831, 'Isaiah 13:15', 'Isaiah', 13, 15, 'هرڅوک چې ونیول شي هغه به په توره باندې ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_15.mp3', '', 1761754199, 1761754199),
(53832, 'Isaiah 13:16', 'Isaiah', 13, 16, 'د هغوی د سترګو په وړاندې به د هغوی ماشومان په وهلو وهلو ووژل شي، د هغوی کورونه به لوټ شي او د هغوی ښځې به بې عزته شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_16.mp3', '', 1761754199, 1761754199),
(53833, 'Isaiah 13:17', 'Isaiah', 13, 17, 'څښتن وایي: «ګورئ، زه به زه به د ماد خلک راوپاروم چې په بابل حمله وکړي. هغوی نه د سپینو زرو پروا لري او نه له سرو زرو سره خوشحاله دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_17.mp3', '', 1761754199, 1761754199),
(53834, 'Isaiah 13:18', 'Isaiah', 13, 18, 'هغوی به په خپلو لیندو او غشو ځوانان ووژني. هغوی به په ماشومانو او حتی په تي رودونکو ماشومانو هم رحم ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_18.mp3', '', 1761754199, 1761754199),
(53835, 'Isaiah 13:19', 'Isaiah', 13, 19, 'د ټولو نه ډېره د شان او شوکت نه ډکه د بابل پاچاهي ده چې د هغه ځای اوسېدونکي کلدانیان ورباندې ویاړي. خو زه څښتن به بابل داسې له منځه یوسم لکه څنګه چې سدوم او عموره مې له منځه وړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_19.mp3', '', 1761754199, 1761754199),
(53836, 'Isaiah 13:20', 'Isaiah', 13, 20, 'هلته به نور هېڅکله هېڅوک هم نه اوسیږي. تر راتلونکو نسلونو به دا ځای هېڅکله اباد نه شي. هېڅ کوم عرب به هلته خپله خېمه ونه دروي او نه به کوم شپون هلته خپلې رمې وڅروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_20.mp3', '', 1761754199, 1761754199),
(53837, 'Isaiah 13:21', 'Isaiah', 13, 21, 'دا به داسې ځای وي چې وحشي حیوانات به په کې اوسیږي او کونګیان به په کې ځالې جوړوي. هلته به شترمرغان اوسیږي او وحشي وزې به د هغو په کنډوالو کې ټوپونه وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_21.mp3', '', 1761754199, 1761754199),
(53838, 'Isaiah 13:22', 'Isaiah', 13, 22, 'له برجونو او له ښکلو ماڼیو څخه به یې د لېوانو او سورلنډیانو اوازونه راځي. د بابل د ویجاړۍ وخت رارسېدلی دی او د هغه عمر لنډ دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah13_verse_22.mp3', '', 1761754199, 1761754199),
(53839, 'Ezekiel 28:1', 'Ezekiel', 28, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_1.mp3', '', 1761754199, 1761754199),
(53840, 'Ezekiel 28:2', 'Ezekiel', 28, 2, '«ای فاني انسانه، د صور پاچا ته ووایه چې زه څښتن تعالی داسې وایم: ‹ته مغروره یې او وایې چې زه یو خدای یم او د بحیرې په منځ کې د خدایانو په تخت ناست یم، په داسې حال کې چې ته یو فاني انسان یې او خدای نه یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_2.mp3', '', 1761754199, 1761754199),
(53841, 'Ezekiel 28:3', 'Ezekiel', 28, 3, 'په رښتیا ته د دانیال نه هم ډېر هوښیار یې او هېڅ کوم راز ستا نه پټ نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_3.mp3', '', 1761754199, 1761754199),
(53842, 'Ezekiel 28:4', 'Ezekiel', 28, 4, 'تا په خپل حکمت او پوهې سره زیات مال او دولت ګټلی دی او خپلې خزانې دې د سرو او سپینو زرو څخه ډکې کړې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_4.mp3', '', 1761754199, 1761754199),
(53843, 'Ezekiel 28:5', 'Ezekiel', 28, 5, 'تا په ډېر حکمت سره د سوداګرۍ کاروبار کړی دی او خپل مال او دولت دې زیات کړی دی. نو ته په خپل مال او دولت باندې ډېر مغرور یې!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_5.mp3', '', 1761754199, 1761754199),
(53844, 'Ezekiel 28:6', 'Ezekiel', 28, 6, 'نو اوس زه څښتن تعالی داسې وایم: ‹په دې خاطر چې ته فکر کوې چې ته د خدای په شان هوښیار یې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_6.mp3', '', 1761754199, 1761754199),
(53845, 'Ezekiel 28:7', 'Ezekiel', 28, 7, 'نو ګوره، زه به په تا باندې پردي او ډېر بې‌رحمه قومونه راولم چې حمله درباندې وکړي. هغوی به ستا ټول ښایسته شیان چې په خپل حکمت باندې دې ګټلي دي، سپک او تباه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_7.mp3', '', 1761754199, 1761754199),
(53846, 'Ezekiel 28:8', 'Ezekiel', 28, 8, 'هغوی به تا د مرګ کندې ته ګوزار کړي او ته به په وحشتناکه توګه د بحیرې په تل کې مړ شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_8.mp3', '', 1761754199, 1761754199),
(53847, 'Ezekiel 28:9', 'Ezekiel', 28, 9, 'کله چې هغوی ستا د وژلو دپاره راشي، نو ته به بیاهم دا وایې چې زه خدای یم؟ کله چې ته د خپلو قاتلانو سره مخامخ شې، نو ته به یو فاني انسان یې، نه خدای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_9.mp3', '', 1761754199, 1761754199),
(53848, 'Ezekiel 28:10', 'Ezekiel', 28, 10, 'ته به د بې‌دینه خلکو په شان د پردیو خلکو د لاسه مړ شې. ما څښتن تعالی داسې ویلي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_10.mp3', '', 1761754199, 1761754199),
(53849, 'Ezekiel 28:11', 'Ezekiel', 28, 11, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_11.mp3', '', 1761754199, 1761754199),
(53850, 'Ezekiel 28:12', 'Ezekiel', 28, 12, '«ای فاني انسانه، د صور د پاچا د سرنوشت په خاطر ویر وکړه. هغه ته ووایه چې څښتن تعالی داسې وایي: ‹په یو وخت کې ته د کمال یو مثال، د حکمت څخه ډک او په ښایست کې پوره وې!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_12.mp3', '', 1761754199, 1761754199),
(53851, 'Ezekiel 28:13', 'Ezekiel', 28, 13, 'ته په عدن کې چې د خدای باغ دی، اوسېدلې او په سرو یاقوتو، زیړو یاقوتو، الماسو، شنو یاقوتو، سرو عقیقو، یشم، د لاجوردو په تیږو، زمردو او لعلو باندې سینګار وې. دا ټولې تیږې په سرو زرو کې په ښکلي شکل ځای په ځای شوې وې. په هغه ورځ چې ته پیدا شوی وې، دا ستا دپاره جوړې شوې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_13.mp3', '', 1761754199, 1761754199),
(53852, 'Ezekiel 28:14', 'Ezekiel', 28, 14, 'ته یو ټاکل شوی ساتونکی اسماني مخلوق وې. ته مې د خدای په سپېڅلي غر باندې ځای په ځای کړې او د ځلېدونکو تیږو په منځ کې به ګرځېدلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_14.mp3', '', 1761754199, 1761754199),
(53853, 'Ezekiel 28:15', 'Ezekiel', 28, 15, 'د کومې ورځې نه چې ته پیدا شوی وې په رښتیا سره چې کامل وې، خو وروسته دې په بدو کارونو باندې پیل وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_15.mp3', '', 1761754199, 1761754199),
(53854, 'Ezekiel 28:16', 'Ezekiel', 28, 16, 'ته په خرڅولو او اخیستلو باندې بوخت وې او دا کار د دې سبب شو چې تا ډېر ظلم وکړ او ګناه ته دې مخه کړه. نو ته مې د خپل سپېڅلي غره څخه ستا د ناپاکۍ له امله وشړلې. ای ساتونکیه اسماني مخلوقه، ته مخکې په ځلېدونکو تیږو کې ګرځېدلې، خو ته مې تباه کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_16.mp3', '', 1761754199, 1761754199),
(53855, 'Ezekiel 28:17', 'Ezekiel', 28, 17, 'ته په خپل ښایست باندې مغرور وې او ستا شهرت د دې سبب شو چې د بې‌عقلو خلکو په شان عمل وکړې. نو له دې امله مې ته په ځمکه راوغورځولې چې د نورو پاچاهانو په نظر کې سپک شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_17.mp3', '', 1761754199, 1761754199),
(53856, 'Ezekiel 28:18', 'Ezekiel', 28, 18, 'تا په اخیستلو او خرڅولو کې دومره ټګي وکړه چې خپل د عبادت ځایونه دې سپک کړل. نو ما ښار ته اور واچاوه او هغه مې د خاورو سره خاورې کړ. نو اوس چې هرڅوک تاته ګوري، نو هغوی به وویني چې ته خاورې ایرې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_18.mp3', '', 1761754199, 1761754199),
(53857, 'Ezekiel 28:19', 'Ezekiel', 28, 19, 'ټول قومونه چې تا پېژني، ستا په لیدلو سخت وېریږي. ته په یو بد سرنوشت باندې اخته شوې او د تل دپاره به له منځه لاړ شې.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel28_verse_19.mp3', '', 1761754199, 1761754199),
