(53899, 'Numbers 8:4', 'Numbers', 8, 4, 'څراغدان د سر څخه نیولې تر پایې پورې د ټکول شویو سرو زرو څخه جوړ شوی ؤ او کټ مټ د هغې نقشې سره سم ؤ لکه څنګه چې څښتن موسی ته ښودلې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_4.mp3', '', 1761754199, 1761754199),
(53900, 'Numbers 8:5', 'Numbers', 8, 5, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_5.mp3', '', 1761754199, 1761754199),
(53901, 'Numbers 8:6', 'Numbers', 8, 6, '«لاویان د نورو اسراییلیانو څخه بېل کړه او پاک یې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_6.mp3', '', 1761754199, 1761754199),
(53902, 'Numbers 8:7', 'Numbers', 8, 7, 'د دې دپاره چې هغوی پاک کړې، نو داسې وکړه: په هغوی باندې پاکوونکې اوبه وشینده او ورته ووایه چې د خپل بدن ټول ویښتان وخرایي او خپل کالي ووینځي، نو هغوی به پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_7.mp3', '', 1761754199, 1761754199),
(53903, 'Numbers 8:8', 'Numbers', 8, 8, 'هغوی دې یو خوسی او د غلې دانې هغه نذرانه راوړي چې د ښو اوړو څخه جوړه شوې وي او د زیتونو تېل ورسره ګډ وي. بل غویی دې د ګناه د نذرانې په توګه راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_8.mp3', '', 1761754199, 1761754199),
(53904, 'Numbers 8:9', 'Numbers', 8, 9, 'بیا به د اسراییلو ټول قوم راوغواړې او لاویانو ته به ووایې چې د سپېڅلې خېمې مخې ته لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_9.mp3', '', 1761754199, 1761754199),
(53905, 'Numbers 8:10', 'Numbers', 8, 10, 'هلته به زما په حضور کې قوم خپل لاسونه د لاویانو په سرونو باندې کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_10.mp3', '', 1761754199, 1761754199),
(53906, 'Numbers 8:11', 'Numbers', 8, 11, 'هارون به لاویان د قوم له خوا د یو ځانګړي سوغات په توګه ماته وړاندې کړي، ترڅو هغوی زما خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_11.mp3', '', 1761754199, 1761754199),
(53907, 'Numbers 8:12', 'Numbers', 8, 12, 'له هغې وروسته دې لاویان خپل لاسونه د غویانو په سرونو باندې کېږدي. بیا به یو غویی د ګناه د نذرانې په توګه قرباني شي او بل د سوځېدونکې نذرانې په توګه، ترڅو د لاویانو دپاره کفاره ادا شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_12.mp3', '', 1761754199, 1761754199),
(53908, 'Numbers 8:13', 'Numbers', 8, 13, 'لاویان د یو ځانګړي سوغات په توګه ماته وقف کړه او هارون او د هغه زامن د هغوی مشران کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_13.mp3', '', 1761754199, 1761754199),
(53909, 'Numbers 8:14', 'Numbers', 8, 14, 'په دې ډول به لاویان د نورو اسراییلیانو څخه بېل کړې او هغوی به زما شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_14.mp3', '', 1761754199, 1761754199),
(53910, 'Numbers 8:15', 'Numbers', 8, 15, 'وروسته له هغې چې تا لاویان پاک او وقف کړل، بیا به هغوی ته اجازه ورکړل شي چې په سپېڅلې خېمه کې کار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers8_verse_15.mp3', '', 1761754199, 1761754199);